begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id) values('ed000000-0000-4000-8000-000000000001'),('ed000000-0000-4000-8000-000000000002'),('ed000000-0000-4000-8000-000000000003');
insert into public.profiles(id) select id from auth.users where id::text like 'ed000000-%';
insert into public.branches(id,code,name) values('ed100000-0000-4000-8000-000000000001','SEC-CONSISTENCY-A','Consistency A'),('ed100000-0000-4000-8000-000000000002','SEC-CONSISTENCY-B','Consistency B');
insert into public.user_roles(user_id,role_id,branch_id) select 'ed000000-0000-4000-8000-000000000001',id,'ed100000-0000-4000-8000-000000000001' from roles where code='SUPER_ADMIN';
insert into public.user_roles(user_id,role_id,branch_id) select 'ed000000-0000-4000-8000-000000000001',id,'ed100000-0000-4000-8000-000000000002' from roles where code='FINANCE';
insert into public.user_roles(user_id,role_id) select 'ed000000-0000-4000-8000-000000000002',id from roles where code='SUPER_ADMIN';
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from roles r cross join permissions p where r.code='SUPER_ADMIN' and p.code='payroll.approve' on conflict do nothing;
set local role authenticated;
select set_config('request.jwt.claim.sub','ed000000-0000-4000-8000-000000000001',true);
select is(has_role('SUPER_ADMIN'),false,'branch SUPER_ADMIN is not a global legacy bypass');
select is(is_global_super_admin(),false,'global helper agrees with role helper');
select is(has_permission('payroll.approve','ed100000-0000-4000-8000-000000000001'),false,'malformed admin cannot fall back to explicit role permissions');
select is(has_role_permission('SUPER_ADMIN','payroll.approve','ed100000-0000-4000-8000-000000000001'),false,'role-specific helper rejects malformed admin scope');
select is(has_permission('payroll.approve','ed100000-0000-4000-8000-000000000002'),true,'valid FINANCE assignment still works in its branch');
select is(finance_action_allowed('payroll.approve','ed100000-0000-4000-8000-000000000001'),false,'cannot mix FINANCE role from another branch');
select is(can_access_branch('ed100000-0000-4000-8000-000000000001'),false,'operational branch helper has no malformed admin bypass');
select is(can_access_student('ed200000-0000-4000-8000-000000000099'),false,'student helper cannot short circuit as global admin');
select throws_ok($$select transition_payroll('ed500000-0000-4000-8000-000000000099',1,'FINALIZED','Denied')$$,'P0001','Unauthorized','legacy payroll RPC denies unauthorized source');
select set_config('request.jwt.claim.sub','ed000000-0000-4000-8000-000000000002',true);
select is(has_role('SUPER_ADMIN'),true,'valid global admin remains compatible');
select is(has_permission('payroll.approve','ed100000-0000-4000-8000-000000000002'),true,'global admin covers branches');
select is(has_permission('nonexistent.permission',null),false,'unknown permission remains denied');
select is(can_access_branch('ed100000-0000-4000-8000-000000000002'),true,'global operational scope remains');
reset role;
update user_roles set valid_until=now()-interval '1 second' where user_id='ed000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(has_role('SUPER_ADMIN'),false,'expired global admin role denied');
select is(is_global_super_admin(),false,'expired global helper denied');
select is(has_permission('payroll.approve',null),false,'expired global permission denied');
reset role;
update user_roles set valid_until=null,valid_from=now()+interval '1 day' where user_id='ed000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(has_role('SUPER_ADMIN'),false,'future global admin denied');
reset role;
update user_roles set valid_from=null,is_active=false where user_id='ed000000-0000-4000-8000-000000000002';
set local role authenticated;
select is(has_role('SUPER_ADMIN'),false,'inactive assignment denied');
reset role;
select set_config('request.jwt.claim.sub','',true);
update user_roles set is_active=true where user_id='ed000000-0000-4000-8000-000000000002';
update profiles set status='SUSPENDED' where id='ed000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','ed000000-0000-4000-8000-000000000002',true);
select is(has_role('SUPER_ADMIN'),false,'suspended profile denies legacy role');
select is(is_global_super_admin(),false,'suspended profile denies global helper');
select is(has_permission('payroll.approve',null),false,'suspended profile denies permissions');
select is(has_role_permission('SUPER_ADMIN','payroll.approve',null),false,'suspended profile denies role permission');
select set_config('request.jwt.claim.sub','ed000000-0000-4000-8000-000000000003',true);
select is(has_role('SUPER_ADMIN'),false,'active profile without assignment denied');
select set_config('request.jwt.claim.sub','',true);
select is(has_role('SUPER_ADMIN'),false,'unauthenticated denied');
reset role;
select ok(not has_table_privilege('anon','public.payroll_off_cycle_correction_runs','SELECT'),'off-cycle view not granted anonymously');
select ok(not has_table_privilege('authenticated','public.payroll_off_cycle_correction_runs','INSERT,UPDATE,DELETE'),'off-cycle view read-only for application role');
select ok(not has_table_privilege('service_role','public.payroll_off_cycle_correction_runs','INSERT,UPDATE,DELETE'),'off-cycle view not writable via service credential');
select ok(not exists(select 1 from unnest(array['financial_approval_requests','financial_approval_events','payroll_corrections'])t where has_table_privilege('service_role','public.'||t,'INSERT,UPDATE,DELETE,TRUNCATE')),'service clients cannot forge approval history');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='finance_private' and (has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))),'private ledger functions inaccessible to clients');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','finance_private') and p.prosecdef and not (coalesce(p.proconfig @> array['search_path=public, pg_temp'],false) or coalesce(p.proconfig @> array['search_path=pg_catalog, pg_temp'],false))),'all security definers retain explicit trusted search path');
select * from finish();
rollback;
